5|using System;
6|using System.Collections.Generic;
7|
8|namespace Markdig.Helpers
9|{
10|    /// <summary>
11|    /// Match a text against a list of ASCII string using internally a tree to speedup the lookup
12|    /// </summary>
13|    public class TextMatchHelper
14|    {
15|        private readonly CharNode root;
16|        private readonly ListCache listCache;
17|
18|        /// <summary>
19|        /// Initializes a new instance of the <see cref="TextMatchHelper"/> class.
20|        /// </summary>
21|        /// <param name="matches">The matches to match against.</param>
22|        /// <exception cref="System.ArgumentNullException"></exception>
23|        public TextMatchHelper(HashSet<string> matches)
24|        {
25|            if (matches == null) throw new ArgumentNullException(nameof(matches));
26|            var list = new List<string>(matches);
27|            root = new CharNode();
28|            listCache = new ListCache();
29|            BuildMap(root, 0, list);
30|            listCache.Clear();
31|        }
32|
33|        /// <summary>
34|        /// Tries to match in the text, at offset position, the list of string matches registered to this instance.
35|        /// </summary>
36|        /// <param name="text">The text.</param>
37|        /// <param name="offset">The offset.</param>
38|        /// <param name="length">The length.</param>
39|        /// <param name="match">The match string if the match was successfull.</param>
40|        /// <returns>
41|        ///   <c>true</c> if the match was successfull; <c>false</c> otherwise
42|        /// </returns>
43|        /// <exception cref="System.ArgumentNullException"></exception>
44|        public bool TryMatch(string text, int offset, int length, out string match)
45|        {
46|            if (text == null) throw new ArgumentNullException(nameof(text));
47|            // TODO(lazy): we should check offset and length for a better exception experience in case of wrong usage
48|            var node = root;
49|            match = null;
50|            while (length > 0)
51|            {
52|                var c = text[offset];
53|                CharNode nextNode;
54|                if (!node.TryGetValue(c, out nextNode))
55|                {
56|                    return false;
57|                }
58|                node = nextNode;
59|                if (node.Content != null)
60|                {
61|                    match = node.Content;
62|                    return true;
63|                }
64|                offset++;
65|                length--;
66|            }
67|            return false;
68|        }
69|
70|        private void BuildMap(CharNode node, int index, List<string> list)
71|        {
72|            // TODO(lazy): This code for building the nodes is not very efficient in terms of memory usage and could be optimized (using structs and indices)
73|            // At least, we are using a cache for the temporary objects build (List<string>)
74|            for (int i = 0; i < list.Count; i++)
75|            {
76|                var str = list[i];
77|                var c = str[index];
78|
79|                CharNode nextNode;
80|                if (!node.TryGetValue(c, out nextNode))
81|                {
82|                    nextNode = new CharNode();
83|                    node.Add(c, nextNode);
84|                }
85|
86|                // We have found a string for this node
87|                if (index + 1 == str.Length)
88|                {
89|                    nextNode.Content = str;
90|                }
91|                else
92|                {
93|                    if (nextNode.NextList == null)
94|                    {
95|                        nextNode.NextList = listCache.Get();
96|                    }
97|                    nextNode.NextList.Add(str);
98|                }
99|            }
100|
101|            foreach (var charList in node)
102|            {
103|                if (charList.Value.NextList != null)
104|                {
105|                    BuildMap(charList.Value, index + 1, charList.Value.NextList);
106|                    listCache.Release(charList.Value.NextList);
107|                    charList.Value.NextList = null;
108|                }
109|            }
110|        }
111|
112|        private class ListCache : DefaultObjectCache<List<string>>
113|        {
114|            protected override void Reset(List<string> instance)
115|            {
116|                instance.Clear();
117|            }
118|        }
119|
120|        private class CharNode : Dictionary<char, CharNode>
121|        {
122|            public List<string> NextList;
123|
124|            public string Content { get; set; }
125|        }
126|    }
127|}

