135|        public static void CheckUnicodeCategory(this char c, out bool space, out bool punctuation)
136|        {
137|            // Credits: code from CommonMark.NET
138|            // Copyright (c) 2014, Kārlis Gaņģis All rights reserved. 
139|            // See license for details:  https://github.com/Knagis/CommonMark.NET/blob/master/LICENSE.md
140|            if (c <= 'ÿ')
141|            {
142|                space = c == '\0' || c == ' ' || (c >= '\t' && c <= '\r') || c == '\u00a0' || c == '\u0085';
143|                punctuation = c == '\0' || (c >= 33 && c <= 47) || (c >= 58 && c <= 64) || (c >= 91 && c <= 96) || (c >= 123 && c <= 126);
144|            }
145|            else
146|            {
147|                var category = CharUnicodeInfo.GetUnicodeCategory(c);
148|                space = category == UnicodeCategory.SpaceSeparator
149|                    || category == UnicodeCategory.LineSeparator
150|                    || category == UnicodeCategory.ParagraphSeparator;
151|                punctuation = !space &&
152|                    (category == UnicodeCategory.ConnectorPunctuation
153|                    || category == UnicodeCategory.DashPunctuation
154|                    || category == UnicodeCategory.OpenPunctuation
155|                    || category == UnicodeCategory.ClosePunctuation
156|                    || category == UnicodeCategory.InitialQuotePunctuation
157|                    || category == UnicodeCategory.FinalQuotePunctuation
158|                    || category == UnicodeCategory.OtherPunctuation);
159|            }
160|        }
