21|        public static void CheckOpenCloseDelimiter(char pc, char c, bool enableWithinWord, out bool canOpen, out bool canClose)
22|        {
23|            // A left-flanking delimiter run is a delimiter run that is 
24|            // (a) not followed by Unicode whitespace, and
25|            // (b) either not followed by a punctuation character, or preceded by Unicode whitespace 
26|            // or a punctuation character. 
27|            // For purposes of this definition, the beginning and the end of the line count as Unicode whitespace.
28|            bool nextIsPunctuation;
29|            bool nextIsWhiteSpace;
30|            bool prevIsPunctuation;
31|            bool prevIsWhiteSpace;
32|            pc.CheckUnicodeCategory(out prevIsWhiteSpace, out prevIsPunctuation);
33|            c.CheckUnicodeCategory(out nextIsWhiteSpace, out nextIsPunctuation);
34|
35|            canOpen = !nextIsWhiteSpace &&
36|                           (!nextIsPunctuation || prevIsWhiteSpace || prevIsPunctuation);
37|
38|
39|            // A right-flanking delimiter run is a delimiter run that is 
40|            // (a) not preceded by Unicode whitespace, and 
41|            // (b) either not preceded by a punctuation character, or followed by Unicode whitespace 
42|            // or a punctuation character. 
43|            // For purposes of this definition, the beginning and the end of the line count as Unicode whitespace.
44|            canClose = !prevIsWhiteSpace &&
45|                            (!prevIsPunctuation || nextIsWhiteSpace || nextIsPunctuation);
46|
47|            if (!enableWithinWord)
48|            {
49|                var temp = canOpen;
50|                // A single _ character can open emphasis iff it is part of a left-flanking delimiter run and either 
51|                // (a) not part of a right-flanking delimiter run or 
52|                // (b) part of a right-flanking delimiter run preceded by punctuation.
53|                canOpen = canOpen && (!canClose || prevIsPunctuation);
54|
55|                // A single _ character can close emphasis iff it is part of a right-flanking delimiter run and either
56|                // (a) not part of a left-flanking delimiter run or 
57|                // (b) part of a left-flanking delimiter run followed by punctuation.
58|                canClose = canClose && (!temp || nextIsPunctuation);
59|            }
60|        }
