4|using System.Collections.Generic;
5|using Markdig.Helpers;
6|using Markdig.Parsers;
7|using Markdig.Syntax;
8|using Markdig.Syntax.Inlines;
9|
10|namespace Markdig.Extensions.Abbreviations
11|{
12|    /// <summary>
13|    /// A block parser for abbreviations.
14|    /// </summary>
15|    /// <seealso cref="Markdig.Parsers.BlockParser" />
16|    public class AbbreviationParser : BlockParser
17|    {
18|        /// <summary>
19|        /// Initializes a new instance of the <see cref="AbbreviationParser"/> class.
20|        /// </summary>
21|        public AbbreviationParser()
22|        {
23|            OpeningCharacters = new[] {'*'};
24|        }
25|
26|        public override BlockState TryOpen(BlockProcessor processor)
27|        {
28|            if (processor.IsCodeIndent)
29|            {
30|                return BlockState.None;
31|            }
32|
33|            // A link must be of the form *[Some Text]: An abbreviation 
34|            var slice = processor.Line;
35|            var startPosition = slice.Start;
36|            var c = slice.NextChar();
37|            if (c != '[')
38|            {
39|                return BlockState.None;
40|            }
41|
42|            SourceSpan labelSpan;
43|            string label;
44|            if (!LinkHelper.TryParseLabel(ref slice, out label, out labelSpan))
45|            {
46|                return BlockState.None;
47|            }
48|
49|            c = slice.CurrentChar;
50|            if (c != ':')
51|            {
52|                return BlockState.None;
53|            }
54|            slice.NextChar();
55|
56|            slice.Trim();
57|
58|            var abbr = new Abbreviation(this)
59|            {
60|                Label = label,
61|                Text = slice,
62|                Span = new SourceSpan(startPosition, slice.End),
63|                Line = processor.LineIndex,
64|                Column = processor.Column,
65|                LabelSpan = labelSpan,
66|            };
67|            if (!processor.Document.HasAbbreviations())
68|            {
69|                processor.Document.ProcessInlinesBegin += DocumentOnProcessInlinesBegin;
70|            }
71|            processor.Document.AddAbbreviation(abbr.Label, abbr);
72|
73|            return BlockState.BreakDiscard;
74|        }
75|
76|        private void DocumentOnProcessInlinesBegin(InlineProcessor inlineProcessor, Inline inline)
77|        {
78|            inlineProcessor.Document.ProcessInlinesBegin -= DocumentOnProcessInlinesBegin;
79|
80|            var abbreviations = inlineProcessor.Document.GetAbbreviations();
81|            // Should not happen, but another extension could decide to remove them, so...
82|            if (abbreviations == null)
83|            {
84|                return;
85|            }
86|
87|            // Build a text matcher from the abbreviations labels
88|            var labels = new HashSet<string>(abbreviations.Keys);
89|            var matcher = new TextMatchHelper(labels);
90|
91|            inlineProcessor.LiteralInlineParser.PostMatch += (InlineProcessor processor, ref StringSlice slice) =>
92|            {
93|                var literal = (LiteralInline) processor.Inline;
94|                var originalLiteral = literal;
95|
96|                ContainerInline container = null;
97|
98|                // This is slow, but we don't have much the choice
99|                var content = literal.Content;
100|                var text = content.Text;
101|                for (int i = content.Start; i < content.End; i++)
102|                {
103|                    string match;
104|                    if (matcher.TryMatch(text, i, content.End - i + 1, out match))
105|                    {
106|                        // The word matched must be embraced by punctuation or whitespace or \0.
107|                        var c = content.PeekCharAbsolute(i - 1);
108|                        if (!(c == '\0' || c.IsAsciiPunctuation() || c.IsWhitespace()))
109|                        {
110|                            continue;
111|                        }
112|                        var indexAfterMatch = i + match.Length;
113|                        c = content.PeekCharAbsolute(indexAfterMatch);
114|                        if (!(c == '\0' || c.IsAsciiPunctuation() || c.IsWhitespace()))
115|                        {
116|                            continue;
117|                        }
118|
119|                        // We should have a match, but in case...
120|                        Abbreviation abbr;
121|                        if (!abbreviations.TryGetValue(match, out abbr))
122|                        {
123|                            continue;
124|                        }
125|
126|                        // If we don't have a container, create a new one
127|                        if (container == null)
128|                        {
129|                            container = new ContainerInline()
130|                            {
131|                                Span = originalLiteral.Span,
132|                                Line = originalLiteral.Line,
133|                                Column = originalLiteral.Column,
134|                            };
135|                        }
136|
137|                        int line;
138|                        int column;
139|                        var abbrInline = new AbbreviationInline(abbr)
140|                        {
141|                            Span =
142|                            {
143|                                Start = processor.GetSourcePosition(i, out line, out column),
144|                            },
145|                            Line = line,
146|                            Column = column
147|                        };
148|                        abbrInline.Span.End = abbrInline.Span.Start + match.Length - 1;
149|
150|                        // Append the previous literal
151|                        if (i > content.Start)
152|                        {
153|                            container.AppendChild(literal);
154|
155|                            literal.Span.End = abbrInline.Span.Start - 1;
156|                            // Truncate it before the abbreviation
157|                            literal.Content.End = i - 1;
158|                        }
159|
160|                        // Appned the abbreviation
161|                        container.AppendChild(abbrInline);
162|
163|                        // If this is the end of the string, clear the literal 
164|                        // and exit
165|                        if (content.End == indexAfterMatch - 1)
166|                        {
167|                            literal = null;
168|                            break;
169|                        }
170|
171|                        // Process the remaining literal
172|                        literal = new LiteralInline()
173|                        {
174|                            Span = new SourceSpan(abbrInline.Span.End + 1, literal.Span.End),
175|                            Line = line,
176|                            Column = column + match.Length,
177|                        };
178|                        content.Start = indexAfterMatch;
179|                        literal.Content = content;
180|
181|                        i = indexAfterMatch - 1;
182|                    }
183|                }
184|
185|                if (container != null)
186|                {
187|                    if (literal != null)
188|                    {
189|                        container.AppendChild(literal);
190|                    }
191|                    processor.Inline = container;
192|                }
193|            };
194|        }
195|    }
