47|        /// <summary>
48|        /// The text of this slice.
49|        /// </summary>
50|        public readonly string Text;
51|
52|        /// <summary>
53|        /// Gets or sets the start position within <see cref="Text"/>.
54|        /// </summary>
55|        public int Start { get; set; }
56|
57|        /// <summary>
58|        /// Gets or sets the end position (inclusive) within <see cref="Text"/>.
59|        /// </summary>
60|        public int End { get; set; }
61|
62|        /// <summary>
63|        /// Gets the length.
64|        /// </summary>
65|        public int Length => End - Start + 1;
66|
67|        /// <summary>
68|        /// Gets the current character.
69|        /// </summary>
70|        public char CurrentChar => Start <= End ? this[Start] : '\0';
71|
72|        /// <summary>
73|        /// Gets a value indicating whether this instance is empty.
74|        /// </summary>
75|        public bool IsEmpty => Start > End;
76|
77|        /// <summary>
78|        /// Gets the <see cref="System.Char"/> at the specified index.
79|        /// </summary>
80|        /// <param name="index">The index.</param>
81|        /// <returns>A character in the slice at the specified index (not from <see cref="Start"/> but from the begining of the slice)</returns>
82|        public char this[int index] => Text[index];
83|
84|        /// <summary>
85|        /// Goes to the next character, incrementing the <see cref="Start" /> position.
86|        /// </summary>
