26|        public override BlockState TryOpen(BlockProcessor processor)
27|        {
28|            if (processor.IsCodeIndent)
29|            {
30|                return BlockState.None;
31|            }
32|
33|            // A link must be of the form *[Some Text]: An abbreviation 
34|            var slice = processor.Line;
35|            var startPosition = slice.Start;
36|            var c = slice.NextChar();
37|            if (c != '[')
38|            {
39|                return BlockState.None;
40|            }
41|
42|            SourceSpan labelSpan;
43|            string label;
44|            if (!LinkHelper.TryParseLabel(ref slice, out label, out labelSpan))
45|            {
46|                return BlockState.None;
47|            }
48|
49|            c = slice.CurrentChar;
50|            if (c != ':')
51|            {
52|                return BlockState.None;
53|            }
54|            slice.NextChar();
55|
56|            slice.Trim();
57|
58|            var abbr = new Abbreviation(this)
59|            {
60|                Label = label,
61|                Text = slice,
62|                Span = new SourceSpan(startPosition, slice.End),
63|                Line = processor.LineIndex,
64|                Column = processor.Column,
65|                LabelSpan = labelSpan,
66|            };
67|            if (!processor.Document.HasAbbreviations())
68|            {
69|                processor.Document.ProcessInlinesBegin += DocumentOnProcessInlinesBegin;
70|            }
71|            processor.Document.AddAbbreviation(abbr.Label, abbr);
72|
73|            return BlockState.BreakDiscard;
74|        }
