76|        private void DocumentOnProcessInlinesBegin(InlineProcessor inlineProcessor, Inline inline)
77|        {
78|            inlineProcessor.Document.ProcessInlinesBegin -= DocumentOnProcessInlinesBegin;
79|
80|            var abbreviations = inlineProcessor.Document.GetAbbreviations();
81|            // Should not happen, but another extension could decide to remove them, so...
82|            if (abbreviations == null)
