187|            previousLineIndexForSliceOffset = 0;
188|            lineOffsets.Clear();
189|            var text = leafBlock.Lines.ToSlice(lineOffsets);
190|            leafBlock.Lines = new StringLineGroup();
191|
192|            int previousStart = -1;
193|
194|            while (!text.IsEmpty)
195|            {
196|                // Security check so that the parser can't go into a crazy infinite loop if one extension is messing
197|                if (previousStart == text.Start)
198|                {
199|                    throw new InvalidOperationException($"The parser is in an invalid infinite loop while trying to parse inlines for block [{leafBlock.GetType().Name}] at position ({leafBlock.ToPositionText()}");
200|                }
201|                previousStart = text.Start;
202|
203|                var c = text.CurrentChar;
204|
205|                var textSaved = text;
206|                var parsers = Parsers.GetParsersForOpeningCharacter(c);
207|                if (parsers != null)
208|                {
209|                    for (int i = 0; i < parsers.Length; i++)
210|                    {
211|                        text = textSaved;
212|                        if (parsers[i].Match(this, ref text))
213|                        {
214|                            goto done;
215|                        }
216|                    }
217|                }
218|                parsers = Parsers.GlobalParsers;
219|                if (parsers != null)
220|                {
221|                    for (int i = 0; i < parsers.Length; i++)
222|                    {
223|                        text = textSaved;
224|                        if (parsers[i].Match(this, ref text))
225|                        {
226|                            goto done;
227|                        }
228|                    }
229|                }
230|
231|                text = textSaved;
232|                // Else match using the default literal inline parser
233|                LiteralInlineParser.Match(this, ref text);
234|
235|                done:
236|                var nextInline = Inline;
237|                if (nextInline != null)
238|                {
239|                    if (nextInline.Parent == null)
240|                    {
241|                        // Get deepest container
242|                        FindLastContainer().AppendChild(nextInline);
243|                    }
244|                }
245|                else
246|                {
247|                    // Get deepest container
248|                    var container = FindLastContainer();
249|
250|                    Inline = container.LastChild is LeafInline ? container.LastChild : container;
251|                    if (Inline == Root)
252|                    {
253|                        Inline = null;
254|                    }
255|                }
256|
257|                if (DebugLog != null)
258|                {
259|                    DebugLog.WriteLine($"** Dump: char '{c}");
260|                    leafBlock.Inline.DumpTo(DebugLog);
261|                }
262|            }
263|
264|            Inline = null;
265|            if (DebugLog != null)
266|            {
267|                DebugLog.WriteLine("** Dump before Emphasis:");
268|                leafBlock.Inline.DumpTo(DebugLog);
269|            }
270|
271|            // Process all delimiters
272|            ProcessDelimiters(0, Root, null, true);
273|
274|            //TransformDelimitersToLiterals();
275|
276|            if (DebugLog != null)
277|            {
278|                DebugLog.WriteLine();
279|                DebugLog.WriteLine("** Dump after Emphasis:");
280|                leafBlock.Inline.DumpTo(DebugLog);
281|            }
