11|    /// <summary>
12|    /// The inline parser for SmartyPants.
13|    /// </summary>
14|    public class TaskListInlineParser : InlineParser
15|    {
16|        /// <summary>
17|        /// Initializes a new instance of the <see cref="TaskListInlineParser"/> class.
18|        /// </summary>
19|        public TaskListInlineParser()
20|        {
21|            OpeningCharacters = new[] {'['};
22|            ListClass = "contains-task-list";
23|            ListItemClass = "task-list-item";
24|        }
25|
26|        /// <summary>
27|        /// Gets or sets the list class used for a task list.
28|        /// </summary>
29|        public string ListClass { get; set; }
30|
31|        /// <summary>
32|        /// Gets or sets the list item class used for a task list.
33|        /// </summary>
34|        public string ListItemClass { get; set; }
35|
36|        public override bool Match(InlineProcessor processor, ref StringSlice slice)
37|        {
38|            // A tasklist is either
39|            // [ ]
40|            // or [x] or [X]
41|
42|            var listItemBlock = processor.Block.Parent as ListItemBlock;
43|
44|            if (listItemBlock == null)
45|            {
46|                return false;
47|            }
48|
49|            var startingPosition = slice.Start;
50|            var c = slice.NextChar();
51|            if (!c.IsSpace() && c != 'x' && c != 'X')
52|            {
53|                return false;
54|            }
55|            if (slice.NextChar() != ']')
56|            {
57|                return false;
58|            }
59|            // Skip last ]
60|            slice.NextChar();
61|
62|            // Create the TaskList
63|            int line;
64|            int column;
65|            var taskItem = new TaskList()
66|            {
67|                Span = { Start = processor.GetSourcePosition(startingPosition, out line, out column)},
68|                Line = line,
69|                Column = column,
70|                Checked = !c.IsSpace()
71|            };
72|            taskItem.Span.End = taskItem.Span.Start + 2;
73|            processor.Inline = taskItem;
74|
75|            // Add proper class for task list
76|            if (!string.IsNullOrEmpty(ListItemClass))
77|            {
78|                listItemBlock.GetAttributes().AddClass(ListItemClass);
79|            }
80|
81|            var listBlock = (ListBlock) listItemBlock.Parent;
82|            if (!string.IsNullOrEmpty(ListClass))
83|            {
84|                listBlock.GetAttributes().AddClass(ListClass);
85|            }
86|
87|            return true;
88|        }
89|    }
