14|    /// <summary>
15|    /// A group of <see cref="StringLine"/>.
16|    /// </summary>
17|    /// <seealso cref="System.Collections.IEnumerable" />
18|    public struct StringLineGroup : IEnumerable
19|    {
20|        /// <summary>
21|        /// Initializes a new instance of the <see cref="StringLineGroup"/> class.
22|        /// </summary>
23|        /// <param name="capacity"></param>
24|        public StringLineGroup(int capacity)
25|        {
26|            if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));
27|            Lines = new StringLine[capacity];
28|            Count = 0;
29|        }
30|
31|        /// <summary>
32|        /// Initializes a new instance of the <see cref="StringLineGroup"/> class.
33|        /// </summary>
34|        /// <param name="text">The text.</param>
35|        /// <exception cref="System.ArgumentNullException"></exception>
36|        public StringLineGroup(string text)
37|        {
38|            if (text == null) throw new ArgumentNullException(nameof(text));
39|            Lines = new StringLine[1];
40|            Count = 0;
41|            Add(new StringSlice(text));
42|        }
43|
44|        /// <summary>
45|        /// Gets the lines.
46|        /// </summary>
47|        public StringLine[] Lines { get; private set; }
48|
49|        /// <summary>
50|        /// Gets the number of lines.
51|        /// </summary>
52|        public int Count { get; private set; }
53|
54|        /// <summary>
55|        /// Clears this instance.
56|        /// </summary>
57|        public void Clear()
58|        {
59|            Array.Clear(Lines, 0, Lines.Length);
60|            Count = 0;
61|        }
62|
63|        /// <summary>
64|        /// Removes the line at the specified index.
65|        /// </summary>
66|        /// <param name="index">The index.</param>
67|        public void RemoveAt(int index)
68|        {
69|            if (Count - 1 == index)
70|            {
71|                Count--;
72|            }
73|            else
74|            {
75|                Array.Copy(Lines, index + 1, Lines, index, Count - index - 1);
76|                Lines[Count - 1] = new StringLine();
77|                Count--;
78|            }
79|        }
80|
81|        /// <summary>
82|        /// Adds the specified line to this instance.
83|        /// </summary>
84|        /// <param name="line">The line.</param>
85|        [MethodImpl(MethodImplOptionPortable.AggressiveInlining)]
86|        public void Add(ref StringLine line)
87|        {
88|            if (Count == Lines.Length) IncreaseCapacity();
89|            Lines[Count++] = line;
90|        }
91|
92|        /// <summary>
93|        /// Adds the specified slice to this instance.
94|        /// </summary>
95|        /// <param name="slice">The slice.</param>
96|        [MethodImpl(MethodImplOptionPortable.AggressiveInlining)]
97|        public void Add(StringSlice slice)
98|        {
99|            if (Count == Lines.Length) IncreaseCapacity();
100|            Lines[Count++] = new StringLine(ref slice);
101|        }
102|
103|        public override string ToString()
104|        {
105|            return ToSlice().ToString();
106|        }
107|
108|        /// <summary>
109|        /// Converts the lines to a single <see cref="StringSlice"/> by concatenating the lines.
110|        /// </summary>
111|        /// <param name="lineOffsets">The position of the `\n` line offsets from the beginning of the returned slice.</param>
112|        /// <returns>A single slice concatenating the lines of this instance</returns>
113|        public StringSlice ToSlice(List<LineOffset> lineOffsets = null)
114|        {
115|            // Optimization case when no lines
116|            if (Count == 0)
117|            {
118|                return new StringSlice(string.Empty);
119|            }
120|
121|            // Optimization case for a single line.
122|            if (Count == 1)
123|            {
124|                if (lineOffsets != null)
125|                {
126|                    lineOffsets.Add(new LineOffset(Lines[0].Position, Lines[0].Column, Lines[0].Slice.Start - Lines[0].Position, Lines[0].Slice.Start, Lines[0].Slice.End + 1));
127|                }
128|                return Lines[0];
129|            }
130|
131|            // Else use a builder
132|            var builder = StringBuilderCache.Local();
133|            int previousStartOfLine = 0;
134|            for (int i = 0; i < Count; i++)
135|            {
136|                if (i > 0)
137|                {
138|                    if (lineOffsets != null)
139|                    {
140|                        lineOffsets.Add(new LineOffset(Lines[i - 1].Position, Lines[i - 1].Column, Lines[i - 1].Slice.Start - Lines[i - 1].Position, previousStartOfLine, builder.Length));
141|                    }
142|                    builder.Append('\n');
143|                    previousStartOfLine = builder.Length;
144|                }
145|                if (!Lines[i].Slice.IsEmpty)
146|                {
147|                    builder.Append(Lines[i].Slice.Text, Lines[i].Slice.Start, Lines[i].Slice.Length);
148|                }
149|            }
150|            if (lineOffsets != null)
151|            {
152|                lineOffsets.Add(new LineOffset(Lines[Count - 1].Position, Lines[Count - 1].Column, Lines[Count - 1].Slice.Start - Lines[Count - 1].Position, previousStartOfLine, builder.Length));
153|            }
154|            var str = builder.ToString();
155|            builder.Length = 0;
156|            return new StringSlice(str);
157|        }
