194|        /// <summary>
195|        /// The iterator used to iterate other the lines.
196|        /// </summary>
197|        /// <seealso cref="ICharIterator" />
198|        public struct Iterator : ICharIterator
199|        {
200|            private readonly StringLineGroup lines;
201|            private int offset;
202|
203|            public Iterator(StringLineGroup lines)
204|            {
205|                this.lines = lines;
206|                Start = -1;
207|                offset = -1;
208|                SliceIndex = 0;
209|                CurrentChar = '\0';
210|                End = -2; 
211|                for (int i = 0; i < lines.Count; i++)
212|                {
213|                    End += lines.Lines[i].Slice.Length + 1; // Add chars
214|                }
215|                NextChar();
216|            }
217|
218|            public int Start { get; private set; }
219|
220|            public char CurrentChar { get; private set; }
221|
222|            public int End { get; private set; }
223|
224|            public bool IsEmpty => Start > End;
225|
226|            public int SliceIndex { get; private set; }
227|
228|            public char NextChar()
229|            {
230|                Start++;
231|                offset++;
232|                if (Start <= End)
233|                {
234|                    var slice = (StringSlice)lines.Lines[SliceIndex];
235|                    if (offset < slice.Length)
236|                    {
237|                        CurrentChar = slice[slice.Start + offset];
238|                    }
239|                    else
240|                    {
241|                        CurrentChar = '\n';
242|                        SliceIndex++;
243|                        offset = -1;
244|                    }
245|                }
246|                else
247|                {
248|                    CurrentChar = '\0';
249|                    Start = End + 1;
250|                    SliceIndex = lines.Count;
251|                    offset--;
252|                }
253|                return CurrentChar;
254|            }
255|
256|            public bool TrimStart()
257|            {
258|                var c = CurrentChar;
259|                bool hasSpaces = false;
260|                while (c.IsWhitespace())
261|                {
262|                    hasSpaces = true;
263|                    c = NextChar();
264|                }
265|                return hasSpaces;
266|            }
267|        }
