274|                Column = column;
275|                Offset = offset;
276|                Start = start;
277|                End = end;
278|            }
279|
280|            public readonly int LinePosition;
281|
282|            public readonly int Column;
283|
284|            public readonly int Offset;
285|
286|            public readonly int Start;
287|
288|            public readonly int End;
289|        }
