200|            private readonly StringLineGroup lines;
201|            private int offset;
202|
203|            public Iterator(StringLineGroup lines)
204|            {
205|                this.lines = lines;
206|                Start = -1;
207|                offset = -1;
208|                SliceIndex = 0;
209|                CurrentChar = '\0';
210|                End = -2; 
211|                for (int i = 0; i < lines.Count; i++)
212|                {
213|                    End += lines.Lines[i].Slice.Length + 1; // Add chars
214|                }
