16|    /// <seealso cref="Markdig.Parsers.InlineParser" />
17|    public class EmojiParser : InlineParser
18|    {
19|        private static readonly Dictionary<string, string> EmojiToUnicodeDefault;
20|        private static readonly Dictionary<string, string> SmileyToEmojiDefault;
21|
22|        private TextMatchHelper textMatchHelper;
23|
24|        /// <summary>
25|        /// Initializes a new instance of the <see cref="EmojiParser"/> class.
26|        /// </summary>
27|        public EmojiParser()
28|        {
29|            OpeningCharacters = null;
30|            EmojiToUnicode = new Dictionary<string, string>(EmojiToUnicodeDefault);
31|            SmileyToEmoji = new Dictionary<string, string>(SmileyToEmojiDefault);
32|        }
33|
34|        /// <summary>
35|        /// Gets the emoji to unicode mapping. This can be modified before this parser is initialized.
36|        /// </summary>
37|        public Dictionary<string, string>  EmojiToUnicode { get; }
38|
39|        /// <summary>
40|        /// Gets the smiley to emoji mapping. This can be modified before this parser is initialized.
41|        /// </summary>
42|        public Dictionary<string, string>  SmileyToEmoji { get; }
43|
44|        public override void Initialize(InlineProcessor processor)
45|        {
46|            var firstChars = new HashSet<char>();
47|            var textToMatch = new HashSet<string>();
48|
49|            foreach (var emoji in EmojiToUnicode)
50|            {
51|                firstChars.Add(emoji.Key[0]);
52|                textToMatch.Add(emoji.Key);
53|            }
54|
55|            foreach (var smiley in SmileyToEmoji)
56|            {
57|                firstChars.Add(smiley.Key[0]);
58|                textToMatch.Add(smiley.Key);
59|            }
60|
61|            textMatchHelper = new TextMatchHelper(textToMatch);
62|
63|            OpeningCharacters = new List<char>(firstChars).ToArray();
64|            Array.Sort(OpeningCharacters);
65|        }
66|
67|        public override bool Match(InlineProcessor processor, ref StringSlice slice)
68|        {
69|            string match;
70|            var startPosition = slice.Start;
71|            if (!textMatchHelper.TryMatch(slice.Text, slice.Start, slice.Length, out match))
72|            {
73|                return false;
74|            }
75|
76|            string emoji;
77|            if (!SmileyToEmoji.TryGetValue(match, out emoji))
78|            {
79|                emoji = match;
80|            }
81|
82|            string unicode;
83|            if (!EmojiToUnicode.TryGetValue(emoji, out unicode))
84|            {
85|                // Should not happen but in case
86|                return false;
87|            }
88|
89|            // Move the cursor to the character after the matched string
90|            slice.Start += match.Length;
91|
92|            // Push the EmojiInline
93|            int line;
94|            int column;
95|            processor.Inline = new EmojiInline(unicode)
96|            {
97|                Span =
98|                {
99|                    Start = processor.GetSourcePosition(startPosition, out line, out column),
100|                },
101|                Line = line,
102|                Column = column,
103|                Match = match
104|            };
105|            processor.Inline.Span.End = processor.Inline.Span.Start + match.Length - 1;
106|
107|            return true;
108|        }
